#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_N 1000
#define MAX_M 10000
#define INF 1000000000

typedef struct Edge {
    int to, rev;
    int cap, cost;
} Edge;

Edge edges[MAX_M * 2];
int edge_count;
int head[MAX_N];
int next_edge[MAX_M * 2];

void add_edge(int from, int to, int cap, int cost) {
    edges[edge_count] = (Edge){to, edge_count + 1, cap, cost};
    next_edge[edge_count] = head[from];
    head[from] = edge_count++;

    edges[edge_count] = (Edge){from, edge_count - 1, 0, -cost};
    next_edge[edge_count] = head[to];
    head[to] = edge_count++;
}

int min_cost_flow(int n, int s, int t, int maxf) {
    int flow = 0, cost = 0;
    int potential[MAX_N];
    int prevv[MAX_N], preve[MAX_N];
    int dist[MAX_N];
    int inqueue[MAX_N];
    int queue[MAX_N * 10];
    int qh, qt;

    memset(potential, 0, sizeof(potential));

    while (flow < maxf) {
        for (int i = 0; i < n; i++) {
            dist[i] = INF;
            inqueue[i] = 0;
        }
        dist[s] = 0;
        qh = qt = 0;
        queue[qt++] = s;
        inqueue[s] = 1;

        while (qh < qt) {
            int v = queue[qh++];
            inqueue[v] = 0;

            for (int i = head[v]; i != -1; i = next_edge[i]) {
                Edge *e = &edges[i];
                if (e->cap > 0) {
                    int nd = dist[v] + e->cost + potential[v] - potential[e->to];
                    if (dist[e->to] > nd) {
                        dist[e->to] = nd;
                        prevv[e->to] = v;
                        preve[e->to] = i;
                        if (!inqueue[e->to]) {
                            queue[qt++] = e->to;
                            inqueue[e->to] = 1;
                        }
                    }
                }
            }
        }

        if (dist[t] == INF) {
            return -1;
        }

        for (int v = 0; v < n; v++) {
            if (dist[v] < INF)
                potential[v] += dist[v];
        }

        int d = maxf - flow;
        for (int v = t; v != s; v = prevv[v]) {
            d = d < edges[preve[v]].cap ? d : edges[preve[v]].cap;
        }

        flow += d;
        cost += d * potential[t];

        for (int v = t; v != s; v = prevv[v]) {
            Edge *e = &edges[preve[v]];
            e->cap -= d;
            edges[e->rev].cap += d;
        }
    }

    return cost;
}

