#define MAXN 505
#define MAXE 10005
#define INF 0x3f3f3f3f

int head[MAXN], nxt[MAXE*2], to[MAXE*2], cap[MAXE*2], cost[MAXE*2], cnt;
int dist[MAXN], inq[MAXN], prevv[MAXN], preve[MAXN];
int queue[MAXN * MAXE];

void init(int n) {
    cnt = 0;
    for (int i = 0; i <= n; i++) head[i] = -1;
}

void addedge(int u, int v, int c, int w) {
    to[cnt] = v; cap[cnt] = c; cost[cnt] = w; nxt[cnt] = head[u]; head[u] = cnt++;
    to[cnt] = u; cap[cnt] = 0; cost[cnt] = -w; nxt[cnt] = head[v]; head[v] = cnt++;
}

int spfa(int s, int t, int n) {
    memset(dist, 0x3f, sizeof(int) * (n + 1));
    memset(inq, 0, sizeof(int) * (n + 1));
    dist[s] = 0;
    int front = 0, back = 0;
    queue[back++] = s;
    inq[s] = 1;
    while (front != back) {
        int u = queue[front++];
        if (front == MAXN * MAXE) front = 0;
        inq[u] = 0;
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (cap[e] > 0 && dist[v] > dist[u] + cost[e]) {
                dist[v] = dist[u] + cost[e];
                prevv[v] = u;
                preve[v] = e;
                if (!inq[v]) {
                    inq[v] = 1;
                    queue[back++] = v;
                    if (back == MAXN * MAXE) back = 0;
                }
            }
        }
    }
    return dist[t] < INF;
}

int main() {
    int n, m, s, t, f;
    scanf("%d %d %d %d %d", &n, &m, &s, &t, &f);
    init(n);
    for (int i = 0; i < m; i++) {
        int u, v, c, w;
        scanf("%d %d %d %d", &u, &v, &c, &w);
        addedge(u, v, c, w);
    }

    long long total_cost = 0;
    int total_flow = 0;

    while (total_flow < f && spfa(s, t, n)) {
        // find max flow along the path
        int aug = f - total_flow;
        int v = t;
        while (v != s) {
            if (cap[preve[v]] < aug) aug = cap[preve[v]];
            v = prevv[v];
        }
        // augment
        v = t;
        while (v != s) {
            cap[preve[v]] -= aug;
            cap[preve[v] ^ 1] += aug;
            v = prevv[v];
        }
        total_flow += aug;
        total_cost += (long long)aug * dist[t];
    }

    if (total_flow < f) {
        printf("-1\n");
    } else {
        printf("%lld\n", total_cost);
    }

    return 0;
}

