typedef long long ll;

typedef struct Edge {
    int to, rev;
    ll cap, cost;
} Edge;

typedef struct Vec {
    Edge *a;
    int sz, cap;
} Vec;

static void vec_push(Vec *v, Edge e) {
    if (v->sz == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->a = (Edge*)realloc(v->a, v->cap * sizeof(Edge));
    }
    v->a[v->sz++] = e;
}

static void add_edge(Vec *g, int u, int v, ll cap, ll cost) {
    Edge a = {v, g[v].sz, cap, cost};
    Edge b = {u, g[u].sz, 0, -cost};
    vec_push(&g[u], a);
    vec_push(&g[v], b);
}

int main(void) {
    int n, m;
    ll required_flow;

    /* Expected input format:
       n m
       s t required_flow
       then m lines:
       u v capacity cost
       Nodes are assumed 0-indexed.
    */
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int s, t;
    if (scanf("%d %d %lld", &s, &t, &required_flow) != 3) return 0;

    Vec *g = (Vec*)calloc(n, sizeof(Vec));
    for (int i = 0; i < m; i++) {
        int u, v;
        ll cap, cost;
        scanf("%d %d %lld %lld", &u, &v, &cap, &cost);
        add_edge(g, u, v, cap, cost);
    }

    const ll INF = (1LL << 60);
    ll *dist = (ll*)malloc(n * sizeof(ll));
    int *inq = (int*)malloc(n * sizeof(int));
    int *pv_node = (int*)malloc(n * sizeof(int));
    int *pv_edge = (int*)malloc(n * sizeof(int));
    int *q = (int*)malloc((n + 5) * sizeof(int));

    ll flow = 0, cost = 0;

    while (flow < required_flow) {
        for (int i = 0; i < n; i++) {
            dist[i] = INF;
            inq[i] = 0;
        }

        int head = 0, tail = 0;
        dist[s] = 0;
        q[tail++] = s;
        inq[s] = 1;

        /* SPFA to find shortest path by cost in residual graph */
        while (head != tail) {
            int u = q[head++];
            if (head == n + 5) head = 0;
            inq[u] = 0;

            for (int i = 0; i < g[u].sz; i++) {
                Edge *e = &g[u].a[i];
                if (e->cap > 0 && dist[u] + e->cost < dist[e->to]) {
                    dist[e->to] = dist[u] + e->cost;
                    pv_node[e->to] = u;
                    pv_edge[e->to] = i;
                    if (!inq[e->to]) {
                        q[tail++] = e->to;
                        if (tail == n + 5) tail = 0;
                        inq[e->to] = 1;
                    }
                }
            }
        }

        if (dist[t] == INF) {
            printf("-1\n");
            for (int i = 0; i < n; i++) free(g[i].a);
            free(g);
            free(dist);
            free(inq);
            free(pv_node);
            free(pv_edge);
            free(q);
            return 0;
        }

        ll add = required_flow - flow;
        for (int v = t; v != s; v = pv_node[v]) {
            Edge *e = &g[pv_node[v]].a[pv_edge[v]];
            if (e->cap < add) add = e->cap;
        }

        for (int v = t; v != s; v = pv_node[v]) {
            Edge *e = &g[pv_node[v]].a[pv_edge[v]];
            e->cap -= add;
            g[v].a[e->rev].cap += add;
        }

        flow += add;
        cost += add * dist[t];
    }

    printf("%lld\n", cost);

    for (int i = 0; i < n; i++) free(g[i].a);
    free(g);
    free(dist);
    free(inq);
    free(pv_node);
    free(pv_edge);
    free(q);

    return 0;
}

