class MinCostFlow {
public:
    int n;
    vector<vector<Edge>> graph;
    vector<long long> dist, potential;
    vector<int> prevv, preve;

    MinCostFlow(int n) : n(n), graph(n), dist(n), potential(n, 0), prevv(n), preve(n) {}

    void add_edge(int from, int to, long long cap, long long cost) {
        graph[from].push_back({to, (int)graph[to].size(), cap, cost});
        graph[to].push_back({from, (int)graph[from].size() - 1, 0, -cost});
    }

    long long min_cost_flow(int s, int t, long long f) {
        long long res = 0;
        fill(potential.begin(), potential.end(), 0);
        while (f > 0) {
            fill(dist.begin(), dist.end(), LLONG_MAX);
            dist[s] = 0;
            priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
            pq.push({0, s});
            while (!pq.empty()) {
                auto [d, v] = pq.top(); pq.pop();
                if (dist[v] < d) continue;
                for (int i = 0; i < (int)graph[v].size(); i++) {
                    Edge &e = graph[v][i];
                    if (e.cap > 0) {
                        long long nd = d + e.cost + potential[v] - potential[e.to];
                        if (dist[e.to] > nd) {
                            dist[e.to] = nd;
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            pq.push({nd, e.to});
                        }
                    }
                }
            }
            if (dist[t] == LLONG_MAX) return -1;
            for (int v = 0; v < n; v++) {
                if (dist[v] < LLONG_MAX)
                    potential[v] += dist[v];
            }
            long long d = f;
            for (int v = t; v != s; v = prevv[v]) {
                d = min(d, graph[prevv[v]][preve[v]].cap);
            }
            f -= d;
            res += d * potential[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = graph[prevv[v]][preve[v]];
                e.cap -= d;
                graph[v][e.rev].cap += d;
            }
        }
        return res;
    }
};

