const int INF = 1e9;

struct Edge {
    int to, cap, cost, flow;
};

struct MCMF {
    int n;
    vector<Edge> edges;
    vector<vector<int>> g;
    vector<int> d, p, a;
    vector<bool> inq;

    MCMF(int n) : n(n), g(n), d(n), p(n), a(n), inq(n) {}

    void addEdge(int from, int to, int cap, int cost) {
        g[from].push_back(edges.size());
        edges.push_back({to, cap, cost, 0});
        g[to].push_back(edges.size());
        edges.push_back({from, 0, -cost, 0});
    }

    pair<int,int> minCostFlow(int s, int t, int maxFlow) {
        int flow = 0, cost = 0;
        while (flow < maxFlow) {
            // SPFA
            fill(d.begin(), d.end(), INF);
            fill(inq.begin(), inq.end(), false);
            d[s] = 0;
            a[s] = maxFlow - flow;
            queue<int> q;
            q.push(s);
            inq[s] = true;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                inq[u] = false;
                for (int id : g[u]) {
                    Edge& e = edges[id];
                    if (e.cap > e.flow && d[e.to] > d[u] + e.cost) {
                        d[e.to] = d[u] + e.cost;
                        p[e.to] = id;
                        a[e.to] = min(a[u], e.cap - e.flow);
                        if (!inq[e.to]) {
                            inq[e.to] = true;
                            q.push(e.to);
                        }
                    }
                }
            }
            if (d[t] == INF) break;
            flow += a[t];
            cost += a[t] * d[t];
            int u = t;
            while (u != s) {
                edges[p[u]].flow += a[t];
                edges[p[u]^1].flow -= a[t];
                u = edges[p[u]^1].to;
            }
        }
        if (flow < maxFlow) return {-1, -1};
        return {flow, cost};
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m, s, t, maxFlow;
    cin >> n >> m >> s >> t >> maxFlow;

    MCMF mcmf(n);

    for (int i = 0; i < m; i++) {
        int u, v, cap, cost;
        cin >> u >> v >> cap >> cost;
        mcmf.addEdge(u, v, cap, cost);
    }

    auto [flow, cost] = mcmf.minCostFlow(s, t, maxFlow);

    if (flow == -1) {
        cout << -1 << endl;
    } else {
        cout << cost << endl;
    }

    return 0;
}

