};

struct MinCostFlow {
    int n;
    vector<vector<Edge>> g;

    MinCostFlow(int n) : n(n), g(n) {}

    void addEdge(int s, int t, long long cap, long long cost) {
        Edge a{t, (int)g[t].size(), cap, cost};
        Edge b{s, (int)g[s].size(), 0, -cost};
        g[s].push_back(a);
        g[t].push_back(b);
    }

    // Returns {flow_sent, min_cost}
    pair<long long, long long> minCostMaxFlow(int s, int t, long long maxf) {
        const long long INF = (1LL << 62);
        long long flow = 0, cost = 0;

        vector<long long> pot(n, 0), dist(n);
        vector<int> pv(n), pe(n);

        // Initial potentials with SPFA to handle negative costs if present
        {
            fill(dist.begin(), dist.end(), INF);
            vector<bool> inq(n, false);
            queue<int> q;
            dist[s] = 0;
            q.push(s);
            inq[s] = true;
            while (!q.empty()) {
                int v = q.front();
                q.pop();
                inq[v] = false;
                for (const auto &e : g[v]) {
                    if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                        dist[e.to] = dist[v] + e.cost;
                        if (!inq[e.to]) {
                            inq[e.to] = true;
                            q.push(e.to);
                        }
                    }
                }
            }
            for (int i = 0; i < n; ++i) {
                if (dist[i] < INF) pot[i] = dist[i];
            }
        }

        while (flow < maxf) {
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            pq.push({0, s});

            while (!pq.empty()) {
                auto [d, v] = pq.top();
                pq.pop();
                if (d != dist[v]) continue;

                for (int i = 0; i < (int)g[v].size(); ++i) {
                    const auto &e = g[v][i];
                    if (e.cap <= 0) continue;
                    long long nd = d + e.cost + pot[v] - pot[e.to];
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int i = 0; i < n; ++i) {
                if (dist[i] < INF) pot[i] += dist[i];
            }

            long long addf = maxf - flow;
            for (int v = t; v != s; v = pv[v]) {
                addf = min(addf, g[pv[v]][pe[v]].cap);
            }

            for (int v = t; v != s; v = pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                e.cap -= addf;
                g[v][e.rev].cap += addf;
            }

            flow += addf;
            cost += addf * pot[t];
        }

        return {flow, cost};
    }
};

