import java.util.*;

public class MinCostFlow {
    static class Edge {
        int to, rev;
        long cap, cost;
        Edge(int to, int rev, long cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MinCostMaxFlow {
        int n;
        List<Edge>[] graph;
        long[] potential, dist;
        int[] prevv, preve;

        @SuppressWarnings("unchecked")
        MinCostMaxFlow(int n) {
            this.n = n;
            graph = new ArrayList[n];
            for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
            potential = new long[n];
            dist = new long[n];
            prevv = new int[n];
            preve = new int[n];
        }

        void addEdge(int from, int to, long cap, long cost) {
            graph[from].add(new Edge(to, graph[to].size(), cap, cost));
            graph[to].add(new Edge(from, graph[from].size() - 1, 0, -cost));
        }

        long minCostFlow(int s, int t, long maxf) {
            long flow = 0, cost = 0;
            Arrays.fill(potential, 0);
            while (flow < maxf) {
                Arrays.fill(dist, Long.MAX_VALUE / 2);
                dist[s] = 0;
                PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
                pq.offer(new long[]{s, 0});
                while (!pq.isEmpty()) {
                    long[] cur = pq.poll();
                    int v = (int) cur[0];
                    if (dist[v] < cur[1]) continue;
                    for (int i = 0; i < graph[v].size(); i++) {
                        Edge e = graph[v].get(i);
                        if (e.cap > 0) {
                            long nd = dist[v] + e.cost + potential[v] - potential[e.to];
                            if (dist[e.to] > nd) {
                                dist[e.to] = nd;
                                prevv[e.to] = v;
                                preve[e.to] = i;
                                pq.offer(new long[]{e.to, nd});
                            }
                        }
                    }
                }
                if (dist[t] == Long.MAX_VALUE / 2) {
                    return -1;
                }
                for (int v = 0; v < n; v++) {
                    if (dist[v] < Long.MAX_VALUE / 2)
                        potential[v] += dist[v];
                }
                long d = maxf - flow;
                for (int v = t; v != s; v = prevv[v]) {
                    d = Math.min(d, graph[prevv[v]].get(preve[v]).cap);
                }
                flow += d;
                cost += d * potential[t];
                for (int v = t; v != s; v = prevv[v]) {
                    Edge e = graph[prevv[v]].get(preve[v]);
                    e.cap -= d;
                    graph[v].get(e.rev).cap += d;
                }
            }
            return cost;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int s = sc.nextInt();
        int t = sc.nextInt();
        long f = sc.nextLong();

        MinCostMaxFlow mcmf = new MinCostMaxFlow(n);
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            long cap = sc.nextLong();
            long cost = sc.nextLong();
            mcmf.addEdge(u, v, cap, cost);
        }

        long result = mcmf.minCostFlow(s, t, f);
        System.out.println(result);
    }
}

