    static void addEdge(int u, int v, int c, int w) {
        to[edgeCnt] = v; cap[edgeCnt] = c; cost[edgeCnt] = w; next[edgeCnt] = head[u]; head[u] = edgeCnt++;
        to[edgeCnt] = u; cap[edgeCnt] = 0; cost[edgeCnt] = -w; next[edgeCnt] = head[v]; head[v] = edgeCnt++;
    }

    static long[] minCostFlow(int s, int t, int maxFlow) {
        long totalCost = 0;
        int totalFlow = 0;

        dist = new int[n];
        prevv = new int[n];
        preve = new int[n];
        inQueue = new boolean[n];

        while (totalFlow < maxFlow) {
            // SPFA
            Arrays.fill(dist, INF);
            dist[s] = 0;
            Queue<Integer> queue = new LinkedList<>();
            queue.add(s);
            inQueue[s] = true;

            while (!queue.isEmpty()) {
                int u = queue.poll();
                inQueue[u] = false;

                for (int e = head[u]; e != -1; e = next[e]) {
                    int v = to[e];
                    if (cap[e] > 0 && dist[u] + cost[e] < dist[v]) {
                        dist[v] = dist[u] + cost[e];
                        prevv[v] = u;
                        preve[v] = e;
                        if (!inQueue[v]) {
                            queue.add(v);
                            inQueue[v] = true;
                        }
                    }
                }
            }

            if (dist[t] == INF) {
                // Cannot reach t
                return new long[]{totalFlow, -1};
            }

            // Find max flow along shortest path
            int d = maxFlow - totalFlow;
            int v = t;
            while (v != s) {
                d = Math.min(d, cap[preve[v]]);
                v = prevv[v];
            }

            // Augment
            v = t;
            while (v != s) {
                cap[preve[v]] -= d;
                cap[preve[v] ^ 1] += d;
                v = prevv[v];
            }

            totalFlow += d;
            totalCost += (long) d * dist[t];
        }

        return new long[]{totalFlow, totalCost};
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int nodes = scanner.nextInt();
        int edges = scanner.nextInt();
        int source = scanner.nextInt();
        int sink = scanner.nextInt();
        int flowNeeded = scanner.nextInt();

        init(nodes + 1);

        for (int i = 0; i < edges; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int c = scanner.nextInt();
            int w = scanner.nextInt();
            addEdge(u, v, c, w);
        }

        long[] result = minCostFlow(source, sink, flowNeeded);

        if (result[0] < flowNeeded) {
            System.out.println(-1);
        } else {
            System.out.println(result[1]);
        }
    }
}

import java.io.*;
import java.util.*;

/*
Minimum Cost to send K units of flow from source to sink.
If impossible, print -1.

Input format assumed:
n m s t k
u1 v1 cap1 cost1
u2 v2 cap2 cost2
...
um vm capm costm

Nodes may be 1-indexed or 0-indexed; this solution works for either as long as
s, t, u, v are within the declared range usage.

Output:
minimum cost, or -1 if not enough capacity exists.

Algorithm:
- Min-Cost Max-Flow using successive shortest augmenting paths
- SPFA once for initial potentials (handles negative edge costs if present)
- Dijkstra with reduced costs for each augmentation
- Complexity suitable for typical competitive programming constraints
*/
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Long.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to, rev;
        long cap, cost;

        Edge(int to, int rev, long cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MinCostMaxFlow {
        int n;
        ArrayList<Edge>[] g;

        @SuppressWarnings("unchecked")
        MinCostMaxFlow(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        }

        void addEdge(int s, int t, long cap, long cost) {
            Edge a = new Edge(t, g[t].size(), cap, cost);
            Edge b = new Edge(s, g[s].size(), 0, -cost);
            g[s].add(a);
            g[t].add(b);
        }

        long[] minCostFlow(int s, int t, long maxf) {
            long INF = Long.MAX_VALUE / 4;
            long[] potential = new long[n];
            long[] dist = new long[n];
            int[] prevNode = new int[n];
            int[] prevEdge = new int[n];

            // Initial SPFA for potentials to support negative costs
            Arrays.fill(potential, INF);
            potential[s] = 0;
            boolean[] inq = new boolean[n];
            ArrayDeque<Integer> q = new ArrayDeque<>();
            q.add(s);
            inq[s] = true;

            while (!q.isEmpty()) {
                int u = q.poll();
                inq[u] = false;
                for (int i = 0; i < g[u].size(); i++) {
                    Edge e = g[u].get(i);
                    if (e.cap > 0 && potential[u] != INF && potential[e.to] > potential[u] + e.cost) {
                        potential[e.to] = potential[u] + e.cost;
                        if (!inq[e.to]) {
                            inq[e.to] = true;
                            q.add(e.to);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                if (potential[i] == INF) potential[i] = 0;
            }

            long flow = 0;
            long cost = 0;

            while (flow < maxf) {
                Arrays.fill(dist, INF);
                dist[s] = 0;

                PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
                pq.add(new long[]{0, s});

                while (!pq.isEmpty()) {
                    long[] cur = pq.poll();
                    long d = cur[0];
                    int u = (int) cur[1];
                    if (d != dist[u]) continue;

                    for (int i = 0; i < g[u].size(); i++) {
                        Edge e = g[u].get(i);
                        if (e.cap <= 0) continue;
                        long nd = d + e.cost + potential[u] - potential[e.to];
                        if (nd < dist[e.to]) {
                            dist[e.to] = nd;
                            prevNode[e.to] = u;
                            prevEdge[e.to] = i;
                            pq.add(new long[]{nd, e.to});
                        }
                    }
                }

                if (dist[t] == INF) break;

                for (int i = 0; i < n; i++) {
                    if (dist[i] < INF) potential[i] += dist[i];
                }

                long add = maxf - flow;
                for (int v = t; v != s; v = prevNode[v]) {
                    Edge e = g[prevNode[v]].get(prevEdge[v]);
                    add = Math.min(add, e.cap);
                }

                for (int v = t; v != s; v = prevNode[v]) {
                    Edge e = g[prevNode[v]].get(prevEdge[v]);
                    e.cap -= add;
                    g[v].get(e.rev).cap += add;
                    cost += add * e.cost;
                }

                flow += add;
            }

            return new long[]{flow, cost};
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        long first = fs.nextLong();
        if (first == Long.MIN_VALUE) return;

        int n = (int) first;
        int m = fs.nextInt();
        int s = fs.nextInt();
        int t = fs.nextInt();
        long k = fs.nextLong();

        // Detect whether nodes are 1-indexed. If s/t/edges include n, we need size n+1.
        int[][] edges = new int[m][2];
        long[] caps = new long[m];
        long[] costs = new long[m];
        int maxNode = Math.max(s, t);

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            long cap = fs.nextLong();
            long cost = fs.nextLong();
            edges[i][0] = u;
            edges[i][1] = v;
            caps[i] = cap;
            costs[i] = cost;
            maxNode = Math.max(maxNode, Math.max(u, v));
        }

        int size = Math.max(n, maxNode + 1);
        MinCostMaxFlow mcmf = new MinCostMaxFlow(size);

        for (int i = 0; i < m; i++) {
            mcmf.addEdge(edges[i][0], edges[i][1], caps[i], costs[i]);
        }

        long[] res = mcmf.minCostFlow(s, t, k);
        if (res[0] < k) {
            System.out.println(-1);
        } else {
            System.out.println(res[1]);
        }
    }
}
